create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,calorie_goal integer not null default 2500 check(calorie_goal between 500 and 15000));
create table if not exists public.foods (id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,name text not null,barcode text,kcal numeric not null check(kcal>=0),protein numeric not null check(protein>=0),carbs numeric not null check(carbs>=0),fat numeric not null check(fat>=0));
create table if not exists public.food_entries (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,food_id uuid references public.foods(id) on delete set null,food_name text not null,kcal_per_100 numeric not null,protein_per_100 numeric not null,carbs_per_100 numeric not null,fat_per_100 numeric not null,grams numeric not null check(grams>0),meal text not null,date date not null,created_at timestamptz default now());
create table if not exists public.weight_logs (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,date date not null,kg numeric not null check(kg>0),unique(user_id,date));
alter table public.profiles enable row level security;alter table public.foods enable row level security;alter table public.food_entries enable row level security;alter table public.weight_logs enable row level security;
create policy "profiles own" on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "foods read own" on public.foods for select to authenticated using(user_id=auth.uid() or user_id is null);
create policy "foods insert own" on public.foods for insert to authenticated with check(user_id=auth.uid());
create policy "foods update own" on public.foods for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "foods delete own" on public.foods for delete to authenticated using(user_id=auth.uid());
create policy "entries own" on public.food_entries for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "weight own" on public.weight_logs for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
